import { useEffect, useMemo, useRef, useState } from "react";
import type { Budget } from "../domain/budget";
import type { Client } from "../domain/client";
import { createFinancingSchedule, createFinancingScheduleByInstallmentAmount, financingSummary, installmentStatus, type Financing } from "../domain/financing";
import { defaultSettings, type Settings } from "../domain/settings";
import type { Work } from "../domain/work";
import { calculatePricing } from "../services/pricing";
import { generateFinancingPdf } from "../services/financing-pdf";

type Props = { clients: Client[]; works: Work[]; budgets: Budget[]; financings: Financing[]; settings: Settings; openFinancingId?: string | null; onSave: (financing: Financing) => Promise<void>; onDelete: (financingId: string) => Promise<void>; onOpenBudget: (budget: Budget) => void };
type ReceiptConfirmation = { installmentNumber: number; undo: boolean };
const currency = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const today = () => new Date().toISOString().slice(0, 10);
const date = (value: string) => new Date(value + "T12:00:00").toLocaleDateString("pt-BR");
const toNumber = (value: string) => Math.max(0, Number(value.replace(",", ".")) || 0);
const rateForEntry = (principal: number, entry: number, settings: Settings) => {
  if (entry <= 0 || principal <= 0) return settings.financingRateNoEntry;
  return entry / principal >= .5 ? settings.financingRateHalfEntry : settings.financingRatePartialEntry;
};

export function FinancingView({ clients, works, budgets, financings, settings, openFinancingId, onSave, onDelete, onOpenBudget }: Props) {
  const [creating, setCreating] = useState(false); const [selected, setSelected] = useState<Financing | null>(null); const [editing, setEditing] = useState<Financing | null>(null); const [preview, setPreview] = useState<Financing | null>(null); const [confirmation, setConfirmation] = useState<ReceiptConfirmation | null>(null); const [notice, setNotice] = useState("");
  const [clientId, setClientId] = useState(""); const [clientSearch, setClientSearch] = useState(""); const [clientPickerOpen, setClientPickerOpen] = useState(false); const [workIds, setWorkIds] = useState<string[]>([]); const [budgetIds, setBudgetIds] = useState<string[]>([]); const [sourceSearch, setSourceSearch] = useState(""); const [sourcePickerOpen, setSourcePickerOpen] = useState(false); const [count, setCount] = useState("10"); const [desiredInstallmentAmount, setDesiredInstallmentAmount] = useState(""); const [entry, setEntry] = useState(""); const [firstPaymentDate, setFirstPaymentDate] = useState(today()); const [customRate, setCustomRate] = useState(""); const [noInterest, setNoInterest] = useState(false); const [error, setError] = useState(""); const [saving, setSaving] = useState(false); const [statusFilter, setStatusFilter] = useState<"Todos" | "Abertos" | "Concluídos" | "Atrasados">("Todos");
  useEffect(() => { if (openFinancingId) setSelected(financings.find((item) => item.id === openFinancingId) || null); }, [openFinancingId, financings]);
  const clientBudgets = budgets.filter((item) => item.clientId === clientId && item.status !== "Rascunho");
  // Orçamentos enviados, abertos, aprovados ou faturados entram no mesmo seletor
  // das obras. O prefixo interno evita confundi-los com uma obra real.
  const clientWorks = [...works.filter((item) => item.clientId === clientId), ...clientBudgets.filter((budget) => !works.some((work) => work.budgetId === budget.id)).map((budget) => ({ id: `budget:${budget.id}`, clientId: budget.clientId, budgetId: budget.id, number: `Orçamento ${budget.number || ""}`.trim(), contractedServices: budget.title, address: budget.workAddress } as Work))];
  const client = clients.find((item) => item.id === clientId);
  const sourceBudgetIds = [...new Set([...workIds.map((workId) => works.find((item) => item.id === workId)?.budgetId || ""), ...budgetIds].filter(Boolean))];
  const sourceBudgets = sourceBudgetIds.map((budgetId) => budgets.find((item) => item.id === budgetId)).filter((item): item is Budget => Boolean(item));
  const chargedValue = sourceBudgets.reduce((sum, budget) => sum + calculatePricing(budget.totalValue, settings, budget.pricingSnapshot).chargedValue, 0);
  const entryAmount = Math.min(chargedValue, toNumber(entry)); const suggestedRate = rateForEntry(chargedValue, entryAmount, settings); const monthlyRate = noInterest ? 0 : customRate === "" ? suggestedRate : toNumber(customRate);
  const filteredClients = clients.filter((item) => item.active !== false && item.name.toLocaleLowerCase("pt-BR").includes(clientSearch.trim().toLocaleLowerCase("pt-BR")));
  const filteredWorks = clientWorks.filter((item) => (item.contractedServices + " " + item.number + " " + item.address).toLocaleLowerCase("pt-BR").includes(sourceSearch.trim().toLocaleLowerCase("pt-BR")));
  const filteredBudgets = clientBudgets.filter((item) => (item.title + " " + item.number + " " + item.workAddress).toLocaleLowerCase("pt-BR").includes(sourceSearch.trim().toLocaleLowerCase("pt-BR")));
  // Compatibilidade visual do seletor antigo: cada nova obra escolhida é adicionada,
  // sem substituir as já selecionadas.
  const workId = workIds[0] || (budgetIds[0] ? `budget:${budgetIds[0]}` : "");
  const setWorkId = (id: string) => {
    if (!id) { setWorkIds([]); setBudgetIds([]); return; }
    if (id.startsWith("budget:")) { const budgetId = id.slice("budget:".length); setBudgetIds((current) => current.includes(budgetId) ? current.filter((item) => item !== budgetId) : [...current, budgetId]); return; }
    setWorkIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  };
  const workSearch = sourceSearch;
  const setWorkSearch = setSourceSearch;
  const workPickerOpen = sourcePickerOpen;
  const setWorkPickerOpen = setSourcePickerOpen;
  const desiredAmount = toNumber(desiredInstallmentAmount);
  const schedule = useMemo(() => sourceBudgets.length && firstPaymentDate ? desiredAmount > 0 ? createFinancingScheduleByInstallmentAmount(chargedValue, desiredAmount, monthlyRate, firstPaymentDate, entryAmount) : createFinancingSchedule(chargedValue, Number(count), monthlyRate, firstPaymentDate, entryAmount) : null, [sourceBudgets.length, count, desiredAmount, firstPaymentDate, chargedValue, monthlyRate, entryAmount]);
  const desiredAmountInvalid = Boolean(sourceBudgets.length && desiredAmount > 0 && !schedule);
  const closeCreate = () => { setCreating(false); setClientId(""); setClientSearch(""); setClientPickerOpen(false); setWorkIds([]); setBudgetIds([]); setSourceSearch(""); setSourcePickerOpen(false); setCount("10"); setDesiredInstallmentAmount(""); setEntry(""); setFirstPaymentDate(today()); setCustomRate(""); setNoInterest(false); setError(""); };
  const save = async (financing: Financing) => { setSaving(true); try { await onSave(financing); setSelected(financing); } catch (cause) { setNotice(cause instanceof Error ? cause.message : "Não foi possível salvar o financiamento."); } finally { setSaving(false); } };
  const create = async (scheduleOverride = schedule, notes = "", name = "") => { if (desiredAmountInvalid) { setError("O valor desejado não quita o saldo em até 120 parcelas com a taxa selecionada. Aumente a parcela, reduza a taxa ou informe uma entrada maior."); return; } if (!client || !sourceBudgets.length || !scheduleOverride) { setError("Selecione o cliente e pelo menos uma obra ou orçamento para financiar."); return; } if (!scheduleOverride.principalAmount) { setError("As origens selecionadas não possuem valor para financiar."); return; } if (!scheduleOverride.financedAmount) { setError("O valor da entrada deve ser menor que o valor total selecionado."); return; } setSaving(true); try { await onSave({ id: crypto.randomUUID(), clientId: client.id, name: name.trim() || undefined, workId: workIds[0] || "", budgetId: sourceBudgetIds[0], workIds, budgetIds: sourceBudgetIds, ...scheduleOverride, notes: notes.trim() || undefined, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }); closeCreate(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível salvar o financiamento."); } finally { setSaving(false); } };
  const deleteSelected = async (financing: Financing) => { if (!window.confirm("Tem certeza que deseja apagar este financiamento? A tabela de parcelas dele será removida e esta ação não poderá ser desfeita. Clientes, obras, orçamentos e os demais dados não serão alterados.")) return; try { await onDelete(financing.id); setSelected(null); setNotice("Financiamento apagado."); } catch (cause) { setNotice(cause instanceof Error ? cause.message : "Não foi possível apagar o financiamento."); } };
  const togglePaid = (number: number) => { if (!selected) return; const installments = selected.installments.map((item) => item.number === number ? { ...item, paidAt: item.paidAt ? undefined : today() } : item); void save({ ...selected, installments, updatedAt: new Date().toISOString() }); };
  const saveInstallmentNote = (number: number, note: string) => { if (!selected) return; const installments = selected.installments.map((item) => item.number === number ? { ...item, note: note.trim() || undefined } : item); void save({ ...selected, installments, updatedAt: new Date().toISOString() }); };
  const fiscal = (number?: number) => { if (!selected) return; const installments = selected.installments.map((item) => item.number === number ? { ...item, fiscalDraftRequestedAt: new Date().toISOString() } : item); void save({ ...selected, installments, updatedAt: new Date().toISOString() }); setNotice(number ? "Solicitação de rascunho fiscal da parcela registrada. A emissão continua bloqueada até a configuração e autorização exigidas." : "Solicitação de rascunho fiscal do financiamento total registrada. A emissão real continua bloqueada."); };
  const selectedClient = selected && clients.find((item) => item.id === selected.clientId);
  const selectedWork = selected && (works.find((item) => item.id === selected.workId) || (() => { const budget = budgets.find((item) => item.id === selected.budgetId); return budget ? { id: "budget:" + budget.id, clientId: budget.clientId, budgetId: budget.id, number: "Orçamento " + (budget.number || ""), contractedServices: budget.title, address: budget.workAddress } as Work : undefined; })());
  const visibleFinancings = financings.filter((item) => { const summary = financingSummary(item); return statusFilter === "Todos" || statusFilter === financingState(summary); });
  return <><div className="flex justify-end"><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white" onClick={() => setCreating(true)}>+ Novo financiamento</button></div>{notice && <p className="mt-4 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">{notice}</p>}<section className="mt-4 rounded-xl border bg-white"><div className="flex items-center justify-between border-b px-5 py-4"><b>Financiamentos cadastrados</b><label className="text-sm font-semibold">Filtrar<select className="ml-2 rounded-lg border bg-white px-3 py-2 text-sm font-normal" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as typeof statusFilter)}><option value="Todos">Todos</option><option value="Abertos">Em aberto</option><option value="Concluídos">Concluídos</option><option value="Atrasados">Atrasados</option></select></label></div>{visibleFinancings.length === 0 ? <p className="p-6 text-sm text-nexus-muted">Nenhum financiamento encontrado para este filtro.</p> : visibleFinancings.map((item) => { const itemClient = clients.find((clientItem) => clientItem.id === item.clientId); const itemWork = works.find((workItem) => workItem.id === item.workId); const summary = financingSummary(item); const state = financingState(summary); return <div className="flex items-center justify-between gap-5 border-b px-5 py-4" key={item.id}><div><b>{itemClient?.name || "Cliente não localizado"}</b><p className="mt-1 text-sm text-nexus-muted">{itemWork?.number || "Obra não localizada"} · {item.installmentsCount}x de {currency.format(item.installments[0]?.amount || 0)}</p><p className="mt-1 text-xs text-nexus-muted">{summary.paidCount} pagas · {summary.remainingCount} restantes{summary.overdueCount ? " · " + summary.overdueCount + " vencida(s)" : ""}</p></div><div className="flex items-center gap-3"><div className="text-right"><span className={"rounded-full px-2 py-1 text-xs font-semibold " + financingStateClass(state)}>{state === "Concluídos" ? "Financiamento concluído" : state === "Atrasados" ? "Financiamento atrasado" : "Financiamento em aberto"}</span><b className="mt-2 block">{currency.format((item.downPaymentAmount || 0) + item.totalFinanced)}</b><p className="text-xs text-nexus-muted">A receber: {currency.format(summary.remaining)}</p></div><button className="rounded-lg border border-nexus-primary px-3 py-2 text-xs font-semibold text-nexus-primary" onClick={() => setSelected(item)}>Visualizar financiamento</button></div></div>; })}</section>{creating && <CreateModal {...{ clientWorks, clientId, setClientId, clientSearch, setClientSearch, clientPickerOpen, setClientPickerOpen, filteredClients, workId, setWorkId, workSearch, setWorkSearch, workPickerOpen, setWorkPickerOpen, filteredWorks, count, setCount, entry, setEntry, firstPaymentDate, setFirstPaymentDate, customRate, setCustomRate, noInterest, setNoInterest, suggestedRate, schedule, chargedValue, monthlyRate, error, saving, closeCreate, create }} />}{selected && selectedClient && selectedWork && <DetailModal financing={selected} client={selectedClient} work={selectedWork} budget={budgets.find((item) => item.id === selected.budgetId)} settings={settings} onClose={() => setSelected(null)} onPreview={() => setPreview(selected)} onToggle={(number, undo) => setConfirmation({ installmentNumber: number, undo })} onNote={saveInstallmentNote} onFiscal={fiscal} onEdit={() => setEditing(selected)} onDelete={() => void deleteSelected(selected)} onOpenBudget={(budgetItem) => { setSelected(null); onOpenBudget(budgetItem); }} />}{editing && <EditFinancingModal financing={editing} onCancel={() => setEditing(null)} onSave={async (updated) => { await onSave(updated); setSelected(updated); setEditing(null); setNotice("Financiamento atualizado."); }} />}{confirmation && selected && <ConfirmationModal installment={selected.installments.find((item) => item.number === confirmation.installmentNumber)!} undo={confirmation.undo} onCancel={() => setConfirmation(null)} onConfirm={() => { togglePaid(confirmation.installmentNumber); setConfirmation(null); }} />}{preview && <FinancingPdfPreview financing={preview} client={clients.find((item) => item.id === preview.clientId)!} work={works.find((item) => item.id === preview.workId)!} settings={settings} onClose={() => setPreview(null)} />}</>;
}

function CreateModal(props: any) {
  const { clientWorks, clientId, setClientId, clientSearch, setClientSearch, clientPickerOpen, setClientPickerOpen, filteredClients, workId, setWorkId, workSearch, setWorkSearch, workPickerOpen, setWorkPickerOpen, filteredWorks, count, setCount, entry, setEntry, firstPaymentDate, setFirstPaymentDate, customRate, setCustomRate, noInterest, setNoInterest, suggestedRate, schedule, chargedValue, monthlyRate, error, saving, closeCreate, create } = props;
  const [selectedSources, setSelectedSources] = useState<string[]>([]);
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");
  const [desiredAmount, setDesiredAmount] = useState("");
  const [desiredAmountError, setDesiredAmountError] = useState("");
  const [previewing, setPreviewing] = useState(false);
  const clientPickerRef = useRef<HTMLDivElement>(null);
  const sourcePickerRef = useRef<HTMLDivElement>(null);
  const selectedClient = filteredClients.find((item: Client) => item.id === clientId);
  const amountSchedule = toNumber(desiredAmount) > 0 ? createFinancingScheduleByInstallmentAmount(chargedValue, toNumber(desiredAmount), monthlyRate, firstPaymentDate, toNumber(entry)) : null;
  const activeSchedule = amountSchedule ?? schedule;
  const sourceLabel = (item: Work) => item.id.startsWith("budget:") ? `Orçamento · ${item.contractedServices || item.number}` : `Obra ${item.number} · ${item.contractedServices || item.address}`;
  const toggleSource = (id: string) => { setSelectedSources((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); setWorkId(id); };
  const save = () => { if (toNumber(desiredAmount) > 0 && !amountSchedule) return setDesiredAmountError("Esse valor não quita o saldo em até 120 parcelas com a taxa atual."); setDesiredAmountError(""); void create(activeSchedule, notes, name); };
  useEffect(() => {
    const closePickers = (event: PointerEvent) => {
      const target = event.target;
      if (!(target instanceof Node)) return;
      if (!clientPickerRef.current?.contains(target)) setClientPickerOpen(false);
      if (!sourcePickerRef.current?.contains(target)) setWorkPickerOpen(false);
    };
    document.addEventListener("pointerdown", closePickers);
    return () => document.removeEventListener("pointerdown", closePickers);
  }, [setClientPickerOpen, setWorkPickerOpen]);

  return <div className="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/40 p-4">
    <section className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-xl">
      <div className="flex items-start justify-between"><div><h2 className="text-xl font-bold">Novo financiamento</h2><p className="mt-1 text-sm text-nexus-muted">Selecione uma ou mais obras e orçamentos enviados. Os valores serão somados em uma única proposta.</p></div><button onClick={closeCreate}>×</button></div>
      <div className="mt-5 grid grid-cols-2 gap-4">
        <div ref={clientPickerRef} className="relative text-sm"><span>Cliente</span><button type="button" className="mt-1 flex w-full items-center justify-between rounded-lg border bg-white px-3 py-2 text-left text-sm" onClick={() => { setClientPickerOpen(!clientPickerOpen); setClientSearch(""); }}>{selectedClient?.name || "Selecione"}<span className="text-nexus-muted">⌄</span></button>{clientPickerOpen && <div className="absolute z-30 mt-1 w-full rounded-lg border bg-white p-2 shadow-lg"><input autoFocus className="w-full rounded border px-2 py-2 text-sm outline-none" placeholder="Buscar cliente" value={clientSearch} onChange={(event) => setClientSearch(event.target.value)} /><div className="mt-1 max-h-44 overflow-y-auto">{filteredClients.length ? filteredClients.map((item: Client) => <button type="button" key={item.id} className="block w-full rounded px-2 py-2 text-left text-sm hover:bg-slate-100" onClick={() => { setClientId(item.id); setWorkId(""); setSelectedSources([]); setClientPickerOpen(false); }}>{item.name}</button>) : <p className="px-2 py-3 text-sm text-nexus-muted">Nenhum cliente encontrado.</p>}</div></div>}</div>
        <label className="text-sm">Nome do financiamento<input className="mt-1 w-full rounded-lg border px-3 py-2" placeholder="Ex.: Reforma completa" value={name} onChange={(event) => setName(event.target.value)} /></label>
        <div ref={sourcePickerRef} className="relative col-span-2 text-sm"><span>Obras e orçamentos</span><button type="button" disabled={!clientId} className="mt-1 flex w-full items-center justify-between rounded-lg border bg-white px-3 py-2 text-left text-sm disabled:bg-slate-100" onClick={() => { setWorkPickerOpen(!workPickerOpen); setWorkSearch(""); }}>{selectedSources.length ? `${selectedSources.length} origem(ns) selecionada(s)` : "Selecione uma ou mais"}<span className="text-nexus-muted">⌄</span></button>{workPickerOpen && <div className="absolute z-20 mt-1 w-full rounded-lg border bg-white p-2 shadow-lg"><input autoFocus className="w-full rounded border px-2 py-2 text-sm outline-none" placeholder="Buscar obra ou orçamento" value={workSearch} onChange={(event) => setWorkSearch(event.target.value)} /><div className="mt-2 max-h-52 space-y-1 overflow-y-auto">{filteredWorks.length ? filteredWorks.map((item: Work) => <label key={item.id} className="flex cursor-pointer items-center gap-3 rounded px-2 py-2 text-sm hover:bg-slate-100"><input type="checkbox" checked={selectedSources.includes(item.id)} onChange={() => toggleSource(item.id)} /><span>{sourceLabel(item)}</span></label>) : <p className="px-2 py-3 text-sm text-nexus-muted">Nenhuma obra ou orçamento enviado encontrado.</p>}</div><div className="mt-2 flex justify-end border-t pt-2"><button type="button" className="rounded-lg bg-nexus-primary px-3 py-2 text-xs font-semibold text-white" onClick={() => setWorkPickerOpen(false)}>Confirmar seleção</button></div></div>}</div>
        <label className="text-sm">Quantidade de parcelas<select className="mt-1 w-full rounded-lg border px-3 py-2" disabled={toNumber(desiredAmount) > 0} value={count} onChange={(event) => setCount(event.target.value)}>{Array.from({ length: 120 }, (_, index) => index + 1).map((value) => <option key={value} value={value}>{value}x</option>)}</select></label>
        <label className="text-sm">Valor desejado por parcela<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" placeholder="Opcional" value={desiredAmount} onChange={(event) => { setDesiredAmount(event.target.value); setDesiredAmountError(""); }} /></label>
        <label className="text-sm">Primeiro vencimento<input className="mt-1 w-full rounded-lg border px-3 py-2" type="date" value={firstPaymentDate} onChange={(event) => setFirstPaymentDate(event.target.value)} /></label>
        <label className="text-sm">Valor de entrada<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" placeholder="0,00" value={entry} onChange={(event) => setEntry(event.target.value)} /></label>
        <label className="col-span-2 text-sm">Observação<textarea className="mt-1 min-h-20 w-full rounded-lg border px-3 py-2" value={notes} onChange={(event) => setNotes(event.target.value)} /></label>
        <div className="col-span-2 rounded-xl border bg-slate-50 p-4"><label className="text-sm">Taxa mensal (%)<input className="mt-1 w-full rounded-lg border bg-white px-3 py-2 disabled:bg-slate-100" type="number" min="0" step="0.01" disabled={noInterest} value={noInterest ? "0" : customRate} placeholder={suggestedRate.toLocaleString("pt-BR")} onChange={(event) => setCustomRate(event.target.value)} /></label><label className="mt-3 flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={noInterest} onChange={(event) => setNoInterest(event.target.checked)} />Financiamento sem juros</label></div>
      </div>
      {activeSchedule && <SchedulePreview schedule={activeSchedule} value={chargedValue} rate={monthlyRate}/>} {desiredAmountError && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{desiredAmountError}</p>} {error && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}
      <div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={closeCreate} disabled={saving}>Cancelar</button><button className="rounded-lg border border-nexus-primary px-4 py-2 text-sm font-semibold text-nexus-primary disabled:opacity-50" onClick={() => setPreviewing(true)} disabled={!activeSchedule || !selectedSources.length}>Ver prévia</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" onClick={save} disabled={saving || !selectedSources.length}>{saving ? "Salvando..." : "Criar financiamento"}</button></div>
    </section>
    {previewing && activeSchedule && <FinancingDraftPreview name={name} clientName={selectedClient?.name || "Cliente"} sourceCount={selectedSources.length} schedule={activeSchedule} value={chargedValue} rate={monthlyRate} onClose={() => setPreviewing(false)} />}
  </div>;
}

function FinancingDraftPreview({ name, clientName, sourceCount, schedule, value, rate, onClose }: { name: string; clientName: string; sourceCount: number; schedule: Pick<Financing, "installments" | "installmentsCount" | "totalFinanced" | "downPaymentAmount" | "financedAmount">; value: number; rate: number; onClose: () => void }) {
  const source = useMemo(() => generateFinancingPdf({ id: "preview", clientId: "preview-client", workId: "preview-work", budgetId: "preview-budget", name: name || "Novo financiamento", principalAmount: value, firstPaymentDate: schedule.installments[0]?.dueDate || today(), ...schedule, installmentRate: rate, notes: `${sourceCount} origem(ns) selecionada(s)`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }, { id: "preview-client", name: clientName } as Client, { id: "preview-work", clientId: "preview-client", budgetId: "preview-budget", number: name || "Financiamento", address: `${sourceCount} origem(ns) selecionada(s)`, contractedServices: name || "Parcelamento" } as Work, defaultSettings, false), [clientName, name, rate, schedule, sourceCount, value]);
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/55 p-4"><section className="flex h-[calc(100vh-2rem)] w-full max-w-5xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><header className="flex items-center justify-between border-b px-5 py-4"><div><p className="text-sm font-medium text-nexus-muted">Prévia em PDF — ainda não salva</p><h2 className="mt-1 text-xl font-bold">{name || "Novo financiamento"}</h2></div><button className="rounded-lg border px-3 py-2 text-sm" onClick={onClose}>Voltar para edição</button></header><iframe className="min-h-0 flex-1 bg-slate-100" title="Prévia do PDF de financiamento" src={source}/></section></div>;
}

function LegacyMultiSourceCreateModal(props: any) {
  const { clientWorks, clientId, setClientId, clientSearch, setClientSearch, clientPickerOpen, setClientPickerOpen, filteredClients, workId, setWorkId, workSearch, setWorkSearch, workPickerOpen, setWorkPickerOpen, filteredWorks, count, setCount, entry, setEntry, firstPaymentDate, setFirstPaymentDate, customRate, setCustomRate, noInterest, setNoInterest, suggestedRate, schedule, chargedValue, monthlyRate, error, saving, closeCreate, create } = props;
  const [selectedSources, setSelectedSources] = useState<string[]>([]);
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");
  const [desiredAmount, setDesiredAmount] = useState("");
  const [desiredAmountError, setDesiredAmountError] = useState("");
  const selectedClient = filteredClients.find((item: Client) => item.id === clientId);
  const amountSchedule = toNumber(desiredAmount) > 0 ? createFinancingScheduleByInstallmentAmount(chargedValue, toNumber(desiredAmount), monthlyRate, firstPaymentDate, toNumber(entry)) : null;
  const activeSchedule = amountSchedule ?? schedule;
  const sourceLabel = (item: Work) => item.id.startsWith("budget:") ? `Orçamento · ${item.contractedServices || item.number}` : `Obra ${item.number} · ${item.contractedServices || item.address}`;
  const toggleSource = (id: string) => { setSelectedSources((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); setWorkId(id); };
  const save = () => { if (toNumber(desiredAmount) > 0 && !amountSchedule) return setDesiredAmountError("Esse valor não quita o saldo em até 120 parcelas com a taxa atual."); setDesiredAmountError(""); void create(activeSchedule, notes, name); };
  return <div className="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/40 p-4"><section className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-xl"><div className="flex items-start justify-between"><div><h2 className="text-xl font-bold">Novo financiamento</h2><p className="mt-1 text-sm text-nexus-muted">Selecione uma ou mais obras e orçamentos enviados. Os valores serão somados em uma única proposta.</p></div><button onClick={closeCreate}>×</button></div><div className="mt-5 grid grid-cols-2 gap-4"><label className="relative text-sm">Cliente<button type="button" className="mt-1 flex w-full items-center justify-between rounded-lg border bg-white px-3 py-2 text-left text-sm" onClick={() => { setClientPickerOpen(true); setClientSearch(""); }}>{selectedClient?.name || "Selecione"}<span className="text-nexus-muted">⌄</span></button>{clientPickerOpen && <div className="absolute z-30 mt-1 w-full rounded-lg border bg-white p-2 shadow-lg"><input autoFocus className="w-full rounded border px-2 py-2 text-sm outline-none" placeholder="Buscar cliente" value={clientSearch} onChange={(event) => setClientSearch(event.target.value)} /><div className="mt-1 max-h-44 overflow-y-auto">{filteredClients.map((item: Client) => <button type="button" key={item.id} className="block w-full rounded px-2 py-2 text-left text-sm hover:bg-slate-100" onClick={() => { setClientId(item.id); setWorkId(""); setSelectedSources([]); setClientPickerOpen(false); }}>{item.name}</button>)}</div></div>}</label><label className="text-sm">Nome do financiamento<input className="mt-1 w-full rounded-lg border px-3 py-2" placeholder="Ex.: Reforma completa - Condomínio" value={name} onChange={(event) => setName(event.target.value)} /></label><div className="relative col-span-2 text-sm">Obras e orçamentos<button type="button" disabled={!clientId} className="mt-1 flex w-full items-center justify-between rounded-lg border bg-white px-3 py-2 text-left text-sm disabled:bg-slate-100" onClick={() => { setWorkPickerOpen(!workPickerOpen); setWorkSearch(""); }}>{selectedSources.length ? `${selectedSources.length} origem(ns) selecionada(s)` : "Selecione uma ou mais"}<span className="text-nexus-muted">⌄</span></button>{workPickerOpen && <div className="absolute z-20 mt-1 w-full rounded-lg border bg-white p-2 shadow-lg"><input autoFocus className="w-full rounded border px-2 py-2 text-sm outline-none" placeholder="Buscar obra ou orçamento" value={workSearch} onChange={(event) => setWorkSearch(event.target.value)} /><div className="mt-2 max-h-52 space-y-1 overflow-y-auto">{filteredWorks.length ? filteredWorks.map((item: Work) => <label key={item.id} className="flex cursor-pointer items-center gap-3 rounded px-2 py-2 text-sm hover:bg-slate-100"><input type="checkbox" checked={selectedSources.includes(item.id)} onChange={() => toggleSource(item.id)} /><span>{sourceLabel(item)}</span></label>) : <p className="px-2 py-3 text-sm text-nexus-muted">Nenhuma obra ou orçamento enviado encontrado.</p>}</div></div>}</div><label className="text-sm">Quantidade de parcelas<select className="mt-1 w-full rounded-lg border px-3 py-2" disabled={toNumber(desiredAmount) > 0} value={count} onChange={(event) => setCount(event.target.value)}>{Array.from({ length: 120 }, (_, index) => index + 1).map((value) => <option key={value} value={value}>{value}x</option>)}</select></label><label className="text-sm">Valor desejado por parcela<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" placeholder="Opcional" value={desiredAmount} onChange={(event) => { setDesiredAmount(event.target.value); setDesiredAmountError(""); }} /></label><label className="text-sm">Primeiro vencimento<input className="mt-1 w-full rounded-lg border px-3 py-2" type="date" value={firstPaymentDate} onChange={(event) => setFirstPaymentDate(event.target.value)} /></label><label className="text-sm">Valor de entrada<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" placeholder="0,00" value={entry} onChange={(event) => setEntry(event.target.value)} /></label><label className="col-span-2 text-sm">Observação<textarea className="mt-1 min-h-20 w-full rounded-lg border px-3 py-2" value={notes} onChange={(event) => setNotes(event.target.value)} /></label><div className="col-span-2 rounded-xl border bg-slate-50 p-4"><label className="text-sm">Taxa mensal (%)<input className="mt-1 w-full rounded-lg border bg-white px-3 py-2 disabled:bg-slate-100" type="number" min="0" step="0.01" disabled={noInterest} value={noInterest ? "0" : customRate} placeholder={suggestedRate.toLocaleString("pt-BR")} onChange={(event) => setCustomRate(event.target.value)} /></label><label className="mt-3 flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={noInterest} onChange={(event) => setNoInterest(event.target.checked)} />Financiamento sem juros</label></div></div>{activeSchedule && <SchedulePreview schedule={activeSchedule} value={chargedValue} rate={monthlyRate}/>} {desiredAmountError && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{desiredAmountError}</p>} {error && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}<div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={closeCreate} disabled={saving}>Cancelar</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" onClick={save} disabled={saving || !selectedSources.length}>{saving ? "Salvando..." : "Criar financiamento"}</button></div></section></div>;
}

function LegacyCreateModal(props: any) {
  const { clientWorks, clientId, setClientId, clientSearch, setClientSearch, clientPickerOpen, setClientPickerOpen, filteredClients, workId, setWorkId, workSearch, setWorkSearch, workPickerOpen, setWorkPickerOpen, filteredWorks, count, setCount, entry, setEntry, firstPaymentDate, setFirstPaymentDate, customRate, setCustomRate, noInterest, setNoInterest, suggestedRate, schedule, chargedValue, monthlyRate, error, saving, closeCreate, create } = props;
  const selectedClient = filteredClients.find((item: Client) => item.id === clientId);
  const selectedWork = clientWorks.find((item: Work) => item.id === workId);
  const workLabel = (item: Work) => item.contractedServices || item.address || item.number;
  const [desiredAmount, setDesiredAmount] = useState("");
  const [desiredAmountError, setDesiredAmountError] = useState("");
  const [notes, setNotes] = useState("");
  const amountSchedule = toNumber(desiredAmount) > 0 ? createFinancingScheduleByInstallmentAmount(chargedValue, toNumber(desiredAmount), monthlyRate, firstPaymentDate, toNumber(entry)) : null;
  const activeSchedule = amountSchedule ?? schedule;
  const save = () => {
    if (toNumber(desiredAmount) > 0 && !amountSchedule) return setDesiredAmountError("Esse valor não quita o saldo em até 120 parcelas com a taxa atual. Aumente a parcela, reduza a taxa ou informe uma entrada maior.");
    setDesiredAmountError("");
    void create(activeSchedule, notes);
  };
  return <div className="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/40 p-8"><section className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-xl"><div className="flex items-start justify-between"><div><h2 className="text-xl font-bold">Novo financiamento</h2><p className="mt-1 text-sm text-nexus-muted">O valor vem do total a cobrar do orçamento da obra selecionada.</p></div><button onClick={closeCreate}>×</button></div><div className="mt-5 grid grid-cols-2 gap-4"><label className="relative text-sm">Cliente<button type="button" className="mt-1 flex w-full items-center justify-between rounded-lg border bg-white px-3 py-2 text-left text-sm" onClick={() => { setClientPickerOpen(true); setClientSearch(""); }}>{selectedClient?.name || "Selecione"}<span className="text-nexus-muted">⌄</span></button>{clientPickerOpen && <div className="absolute z-20 mt-1 w-full rounded-lg border bg-white p-2 shadow-lg"><div className="flex items-center rounded-md border px-2"><span className="text-nexus-muted">⌕</span><input autoFocus className="w-full border-0 px-2 py-2 text-sm outline-none" placeholder="Buscar cliente" value={clientSearch} onChange={(event) => setClientSearch(event.target.value)} /></div><div className="mt-1 max-h-44 overflow-y-auto">{filteredClients.length ? filteredClients.map((item: Client) => <button type="button" key={item.id} className="block w-full rounded px-2 py-2 text-left text-sm hover:bg-slate-100" onClick={() => { setClientId(item.id); setWorkId(""); setClientPickerOpen(false); }}>{item.name}</button>) : <p className="px-2 py-3 text-sm text-nexus-muted">Nenhum cliente encontrado.</p>}</div></div>}</label><label className="relative text-sm">Obra<button type="button" disabled={!clientId} className="mt-1 flex w-full items-center justify-between rounded-lg border bg-white px-3 py-2 text-left text-sm disabled:bg-slate-100" onClick={() => { setWorkPickerOpen(true); setWorkSearch(""); }}>{selectedWork ? workLabel(selectedWork) : "Selecione"}<span className="text-nexus-muted">⌄</span></button>{workPickerOpen && <div className="absolute z-10 mt-1 w-full rounded-lg border bg-white p-2 shadow-lg"><div className="flex items-center rounded-md border px-2"><span className="text-nexus-muted">⌕</span><input autoFocus className="w-full border-0 px-2 py-2 text-sm outline-none" placeholder="Buscar obra" value={workSearch} onChange={(event) => setWorkSearch(event.target.value)} /></div><div className="mt-1 max-h-44 overflow-y-auto">{filteredWorks.length ? filteredWorks.map((item: Work) => <button type="button" key={item.id} className="block w-full rounded px-2 py-2 text-left text-sm hover:bg-slate-100" onClick={() => { setWorkId(item.id); setWorkPickerOpen(false); }}>{item.number} · {workLabel(item)}</button>) : <p className="px-2 py-3 text-sm text-nexus-muted">Nenhuma obra encontrada.</p>}</div></div>}</label>
<label className="text-sm">Quantidade de parcelas<select className="mt-1 w-full rounded-lg border px-3 py-2 disabled:cursor-not-allowed disabled:bg-slate-100" disabled={toNumber(desiredAmount) > 0} value={count} onChange={(event) => setCount(event.target.value)}>{Array.from({ length: 120 }, (_, index) => index + 1).map((value) => <option key={value} value={value}>{value}x</option>)}</select></label>
<label className="text-sm">Valor desejado por parcela<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" placeholder="Opcional: calcula a quantidade" value={desiredAmount} onChange={(event) => { setDesiredAmount(event.target.value); setDesiredAmountError(""); }} /></label>
<label className="text-sm">Primeiro vencimento<input className="mt-1 w-full rounded-lg border px-3 py-2" type="date" value={firstPaymentDate} onChange={(event) => setFirstPaymentDate(event.target.value)} /></label>
<label className="col-span-2 text-sm">Valor de entrada<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" placeholder="0,00 (sem entrada)" value={entry} onChange={(event) => setEntry(event.target.value)} /></label>
<label className="col-span-2 text-sm">Observação<textarea className="mt-1 min-h-20 w-full rounded-lg border px-3 py-2" placeholder="Ex.: Parcelamento do condomínio" value={notes} onChange={(event) => setNotes(event.target.value)} /></label>
<div className="col-span-2 rounded-xl border bg-slate-50 p-4"><div className="flex items-end gap-4"><label className="flex-1 text-sm">Taxa mensal (%)<input className="mt-1 w-full rounded-lg border bg-white px-3 py-2 disabled:bg-slate-100" type="number" min="0" step="0.01" disabled={noInterest} value={noInterest ? "0" : customRate} placeholder={suggestedRate.toLocaleString("pt-BR")} onChange={(event) => setCustomRate(event.target.value)} /></label><label className="mb-2 flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={noInterest} onChange={(event) => setNoInterest(event.target.checked)} />Financiamento sem juros</label></div><p className="mt-2 text-xs text-nexus-muted">Taxa padrão sugerida: {suggestedRate.toLocaleString("pt-BR")}% ao mês. Esta alteração vale apenas para este financiamento.</p></div></div>
{activeSchedule && <SchedulePreview schedule={activeSchedule} value={chargedValue} rate={monthlyRate}/>} {desiredAmountError && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{desiredAmountError}</p>} {error && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}<div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={closeCreate} disabled={saving}>Cancelar</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" onClick={save} disabled={saving}>{saving ? "Salvando..." : "Criar financiamento"}</button></div></section></div>;
}
function EditFinancingModal({ financing, onCancel, onSave }: { financing: Financing; onCancel: () => void; onSave: (financing: Financing) => Promise<void> }) {
  // Financiamentos anteriores ao campo de nome eram exibidos simplesmente como
  // "Financiamento". Mantemos esse nome ao abrir a edição, em vez de mostrar
  // um campo vazio e induzir o usuário a preenchê-lo novamente.
  const originalName = financing.name?.trim() || "Financiamento";
  const [name, setName] = useState(originalName);
  const [principal, setPrincipal] = useState(String(financing.principalAmount));
  const [entry, setEntry] = useState(String(financing.downPaymentAmount || ""));
  const [count, setCount] = useState(String(financing.installmentsCount));
  const [rate, setRate] = useState(String(financing.installmentRate));
  const [firstPaymentDate, setFirstPaymentDate] = useState(financing.firstPaymentDate);
  const [notes, setNotes] = useState(financing.notes || "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    setName(financing.name?.trim() || "Financiamento");
    setPrincipal(String(financing.principalAmount));
    setEntry(String(financing.downPaymentAmount || ""));
    setCount(String(financing.installmentsCount));
    setRate(String(financing.installmentRate));
    setFirstPaymentDate(financing.firstPaymentDate);
    setNotes(financing.notes || "");
    setError("");
  }, [financing]);
  const principalAmount = toNumber(principal);
  const entryAmount = toNumber(entry);
  const installmentRate = toNumber(rate);
  const schedule = useMemo(() => principalAmount > 0 && entryAmount < principalAmount && firstPaymentDate ? createFinancingSchedule(principalAmount, Number(count), installmentRate, firstPaymentDate, entryAmount) : null, [principalAmount, entryAmount, count, installmentRate, firstPaymentDate]);
  const submit = async () => {
    if (!schedule) return setError("Informe um valor total maior que a entrada e uma data de primeiro vencimento.");
    if (!window.confirm("Salvar substituirá os valores e a tabela de parcelas deste financiamento. Recebimentos já registrados serão preservados nas parcelas equivalentes. Deseja continuar?")) return;
    const previous = new Map(financing.installments.map((item) => [item.number, item]));
    const installments = schedule.installments.map((item) => ({ ...item, paidAt: previous.get(item.number)?.paidAt, fiscalDraftRequestedAt: previous.get(item.number)?.fiscalDraftRequestedAt, note: previous.get(item.number)?.note }));
    setSaving(true);
    try { await onSave({ ...financing, name: name.trim() || undefined, principalAmount, downPaymentAmount: entryAmount, financedAmount: schedule.financedAmount, installmentRate, installmentsCount: schedule.installmentsCount, firstPaymentDate, totalFinanced: schedule.totalFinanced, installments, notes: notes.trim() || undefined, updatedAt: new Date().toISOString() }); } finally { setSaving(false); }
  };
  return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-4"><section className="max-h-[calc(100vh-2rem)] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><h2 className="text-xl font-bold">Editar financiamento</h2><p className="mt-2 text-sm text-nexus-muted">Altere todos os valores e condições do parcelamento. Cliente e origens permanecem vinculados para preservar a consistência financeira.</p></div><button className="text-xl text-nexus-muted" onClick={onCancel}>×</button></div><div className="mt-5 grid grid-cols-2 gap-4"><label className="col-span-2 text-sm">Nome atual do financiamento<input className="mt-1 w-full rounded-lg border px-3 py-2" value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Reforma completa" /></label><label className="text-sm">Valor total da proposta<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" value={principal} onChange={(event) => setPrincipal(event.target.value)} /></label><label className="text-sm">Valor de entrada<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" value={entry} onChange={(event) => setEntry(event.target.value)} /></label><label className="text-sm">Quantidade de parcelas<select className="mt-1 w-full rounded-lg border px-3 py-2" value={count} onChange={(event) => setCount(event.target.value)}>{Array.from({ length: 120 }, (_, index) => index + 1).map((value) => <option key={value} value={value}>{value}x</option>)}</select></label><label className="text-sm">Taxa mensal (%)<input className="mt-1 w-full rounded-lg border px-3 py-2" type="number" min="0" step="0.01" value={rate} onChange={(event) => setRate(event.target.value)} /></label><label className="text-sm">Primeiro vencimento<input className="mt-1 w-full rounded-lg border px-3 py-2" type="date" value={firstPaymentDate} onChange={(event) => setFirstPaymentDate(event.target.value)} /></label><label className="col-span-2 text-sm">Observação<textarea className="mt-1 min-h-24 w-full rounded-lg border px-3 py-2" value={notes} onChange={(event) => setNotes(event.target.value)} /></label></div>{schedule && <SchedulePreview schedule={schedule} value={principalAmount} rate={installmentRate}/>} {error && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{error}</p>}<div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={onCancel} disabled={saving}>Cancelar</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" onClick={() => void submit()} disabled={saving}>{saving ? "Salvando..." : "Salvar financiamento"}</button></div></section></div>;
}

function LegacyEditFinancingModal({ financing, onCancel, onSave }: { financing: Financing; onCancel: () => void; onSave: (financing: Financing) => Promise<void> }) {
  const [notes, setNotes] = useState(financing.notes || ""); const [saving, setSaving] = useState(false);
  const submit = async () => { if (!window.confirm("Ao salvar, os dados anteriores deste financiamento serão substituídos pelos novos dados. Deseja continuar?")) return; setSaving(true); try { await onSave({ ...financing, notes: notes.trim() || undefined, updatedAt: new Date().toISOString() }); } finally { setSaving(false); } };
  return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-6"><section className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><h2 className="text-xl font-bold">Editar financiamento</h2><p className="mt-2 text-sm text-nexus-muted">Edite a observação sem alterar a tabela e os valores já registrados.</p><label className="mt-5 block text-sm font-medium">Observação<textarea className="mt-1 min-h-28 w-full rounded-lg border px-3 py-2" placeholder="Ex.: Parcelamento do condomínio" value={notes} onChange={(event) => setNotes(event.target.value)} /></label><div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={onCancel} disabled={saving}>Cancelar</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white" onClick={() => void submit()} disabled={saving}>{saving ? "Salvando..." : "Salvar alterações"}</button></div></section></div>;
}
function DetailModal({ financing, client, work, budget, settings, onClose, onPreview, onToggle, onNote, onFiscal, onEdit, onDelete, onOpenBudget }: { financing: Financing; client: Client; work: Work; budget?: Budget; settings: Settings; onClose: () => void; onPreview: () => void; onToggle: (number: number, undo: boolean) => void; onNote: (number: number, note: string) => void; onFiscal: (number?: number) => void; onEdit: () => void; onDelete: () => void; onOpenBudget: (budget: Budget) => void }) { const [noteFor, setNoteFor] = useState<Financing["installments"][number] | null>(null); const summary = financingSummary(financing); const entry = financing.downPaymentAmount || 0; const state = financingState(summary); return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-6"><section className="flex max-h-[92vh] w-full max-w-5xl flex-col overflow-hidden rounded-2xl bg-white shadow-xl"><header className="flex items-start justify-between border-b px-6 py-5"><div><p className="text-sm text-nexus-muted">{client.name} · {work.number}</p><div className="mt-1 flex items-center gap-2"><h2 className="text-2xl font-bold">{financing.name?.trim() || "Financiamento"}</h2>{state === "Concluídos" && <span className="rounded-full bg-emerald-100 px-2 py-1 text-xs font-semibold text-emerald-800">Financiamento concluído</span>}</div></div><div className="flex gap-2"><button className="rounded-lg border border-nexus-primary px-3 py-2 text-sm font-semibold text-nexus-primary disabled:opacity-50" disabled={!budget} onClick={() => budget && onOpenBudget(budget)}>Ver orçamento</button><button className="rounded-lg border px-3 py-2 text-sm font-semibold" onClick={onEdit}>Editar financiamento</button><button className="rounded-lg border border-red-300 px-3 py-2 text-sm font-semibold text-red-700" onClick={onDelete}>Apagar financiamento</button><button className="rounded-lg border px-3 py-2 text-sm font-semibold" onClick={onPreview}>Ver prévia do PDF</button><button className="rounded-lg border px-3 py-2 text-sm font-semibold" onClick={() => generateFinancingPdf(financing, client, work, settings)}>Baixar PDF</button><button className="rounded-lg border px-3 py-2 text-sm" onClick={onClose}>Fechar</button></div></header><div className="overflow-y-auto p-6"><div className="grid grid-cols-3 gap-3 lg:grid-cols-6"><Card label="Valor da obra" value={financing.principalAmount}/><Card label="Entrada" value={entry} tone="green"/><Card label="Parcelado" value={financing.totalFinanced}/><Card label="Já recebido" value={summary.paid} tone="green"/><Card label="Falta receber" value={summary.remaining}/><Card label="Vencidas" text={String(summary.overdueCount)} tone={summary.overdueCount ? "red" : "slate"}/></div>{financing.notes && <p className="mt-4 rounded-lg bg-slate-50 p-3 text-sm"><b>Observação:</b> {financing.notes}</p>}<div className="mt-6 flex items-center justify-between"><div><h3 className="font-semibold">Tabela de parcelas</h3><p className="mt-1 text-sm text-nexus-muted">Taxa registrada: {financing.installmentRate.toLocaleString("pt-BR")}% ao mês</p></div><button className="rounded-lg border border-nexus-primary px-3 py-2 text-sm font-semibold text-nexus-primary" onClick={() => onFiscal()}>Preparar nota fiscal total</button></div><div className="mt-3 overflow-hidden rounded-xl border"><div className="grid grid-cols-[1fr_1.2fr_1fr_1fr_2fr] bg-slate-50 px-4 py-3 text-xs font-semibold uppercase text-nexus-muted"><span>Parcela</span><span>Vencimento</span><span>Valor</span><span>Status</span><span className="text-right">Ações</span></div>{financing.installments.map((installment) => { const status = installmentStatus(installment); const style = status === "Pago" ? "bg-emerald-100 text-emerald-800" : status === "Vencida" ? "bg-red-100 text-red-800" : "bg-amber-100 text-amber-800"; return <div className="grid grid-cols-[1fr_1.2fr_1fr_1fr_2fr] items-center border-t px-4 py-3 text-sm" key={installment.number}><span>{installment.number} de {financing.installmentsCount}</span><span>{date(installment.dueDate)}</span><b>{currency.format(installment.amount)}</b><span><i className={"rounded-full px-2 py-1 text-xs not-italic " + style}>{status}</i></span><div className="flex justify-end gap-2"><button className="w-28 whitespace-nowrap rounded border px-2 py-1 text-xs" title="Observação da parcela" onClick={() => setNoteFor(installment)}>{installment.note ? "Visualizar nota" : "Adicionar nota"}</button><button className="inline-flex w-32 justify-center whitespace-nowrap rounded border px-2 py-1 text-xs" onClick={() => onToggle(installment.number, Boolean(installment.paidAt))}>{installment.paidAt ? "Desfazer recebimento" : "Registrar recebido"}</button><button className="rounded border border-nexus-primary px-2 py-1 text-xs text-nexus-primary" onClick={() => onFiscal(installment.number)}>{installment.fiscalDraftRequestedAt ? "Rascunho solicitado" : "Preparar nota fiscal"}</button></div></div>; })}</div></div></section>{noteFor && <InstallmentNoteModal installment={noteFor} onCancel={() => setNoteFor(null)} onSave={(note) => { onNote(noteFor.number, note); setNoteFor(null); }} />}</div>; }
function SchedulePreview({ schedule, value, rate }: { schedule: Pick<Financing, "installments" | "installmentsCount" | "totalFinanced" | "downPaymentAmount" | "financedAmount">; value: number; rate: number }) { return <div className="mt-5 rounded-xl bg-slate-50 p-4"><div className="grid grid-cols-2 gap-3 text-sm lg:grid-cols-5"><Card label="Valor da obra" value={value}/><Card label="Entrada" value={schedule.downPaymentAmount}/><Card label="Saldo parcelado" value={schedule.financedAmount}/><Card label="Taxa mensal" text={rate.toLocaleString("pt-BR") + "%"}/><Card label="Total das parcelas" value={schedule.totalFinanced}/></div><div className="mt-3 text-xs text-nexus-muted">A taxa pode ser definida como padrão nas Configurações ou ajustada somente neste financiamento.</div><div className="mt-4 max-h-48 overflow-y-auto rounded-lg border bg-white">{schedule.installments.map((item) => <div className="grid grid-cols-3 border-b px-3 py-2 text-sm" key={item.number}><span>{item.number} de {schedule.installmentsCount}</span><span>{date(item.dueDate)}</span><span className="text-right font-medium">{currency.format(item.amount)}</span></div>)}</div></div>; }
function Card({ label, value, text, tone = "slate" }: { label: string; value?: number; text?: string; tone?: "slate" | "green" | "red" }) { return <div className={"rounded-xl border p-3 " + (tone === "green" ? "bg-emerald-50" : tone === "red" ? "bg-red-50" : "bg-white")}><p className="text-xs uppercase text-nexus-muted">{label}</p><b className="mt-1 block">{text ?? currency.format(value || 0)}</b></div>; }
function financingState(summary: ReturnType<typeof financingSummary>): "Abertos" | "Concluídos" | "Atrasados" { if (summary.remainingCount === 0) return "Concluídos"; return summary.overdueCount > 0 ? "Atrasados" : "Abertos"; }
function financingStateClass(state: ReturnType<typeof financingState>) { return state === "Concluídos" ? "bg-emerald-100 text-emerald-800" : state === "Atrasados" ? "bg-red-100 text-red-800" : "bg-amber-100 text-amber-800"; }
function InstallmentNoteModal({ installment, onCancel, onSave }: { installment: Financing["installments"][number]; onCancel: () => void; onSave: (note: string) => void }) { const [note, setNote] = useState(installment.note || ""); return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-6"><section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><h2 className="text-xl font-bold">Observação da parcela {installment.number}</h2><textarea autoFocus className="mt-4 min-h-32 w-full rounded-lg border px-3 py-2 text-sm" placeholder="Escreva uma observação sobre esta parcela" value={note} onChange={(event) => setNote(event.target.value)} /><div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={onCancel}>Cancelar</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white" onClick={() => onSave(note)}>Salvar observação</button></div></section></div>; }
function ConfirmationModal({ installment, undo, onCancel, onConfirm }: { installment: Financing["installments"][number]; undo: boolean; onCancel: () => void; onConfirm: () => void }) { return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-6"><section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><h2 className="text-xl font-bold">{undo ? "Desfazer recebimento?" : "Confirmar recebimento?"}</h2><p className="mt-3 text-sm text-nexus-muted">{undo ? "Tem certeza que deseja desfazer o recebimento" : "Tem certeza que você recebeu"} da parcela {installment.number}, no valor de {currency.format(installment.amount)}?</p><div className="mt-6 flex justify-end gap-3"><button className="rounded-lg border px-4 py-2 text-sm" onClick={onCancel}>Não</button><button className="rounded-lg bg-nexus-primary px-4 py-2 text-sm font-semibold text-white" onClick={onConfirm}>Sim, {undo ? "desfazer" : "confirmar"}</button></div></section></div>; }
function FinancingPdfPreview({ financing, client, work, settings, onClose }: { financing: Financing; client: Client; work: Work; settings: Settings; onClose: () => void }) { const source = generateFinancingPdf(financing, client, work, settings, false); return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-6"><section className="flex h-[92vh] w-full max-w-5xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><header className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-bold text-nexus-ink">Prévia da tabela de parcelamento</h2><p className="text-sm text-nexus-muted">Visualização interna - o PDF não foi baixado.</p></div><button className="rounded-lg border px-3 py-2 text-sm" onClick={onClose}>Fechar</button></header><iframe className="min-h-0 flex-1 bg-slate-100" title="Prévia do PDF de financiamento" src={source}/></section></div>; }
